"use strict";(self.webpackChunkmy_website=self.webpackChunkmy_website||[]).push([[6324],{9760:e=>{e.exports=JSON.parse('{"blogPosts":[{"id":"comptia-security-plus-certification","metadata":{"permalink":"/my-blog/blog/comptia-security-plus-certification","source":"@site/blog/2025-06-09-comptia-security-plus.md","title":"CompTIA Security+ Certification","description":"About","date":"2025-06-09T00:00:00.000Z","formattedDate":"June 9, 2025","tags":[{"label":"security","permalink":"/my-blog/blog/tags/security"},{"label":"cyber","permalink":"/my-blog/blog/tags/cyber"},{"label":"certification","permalink":"/my-blog/blog/tags/certification"}],"readingTime":0.965,"hasTruncateMarker":false,"authors":[{"name":"Dudu Kling","title":"Blog Owner","url":"https://github.com/DuduKling","imageURL":"https://dudukling.github.io/assets/images/avatar.png","key":"dudu"}],"frontMatter":{"slug":"comptia-security-plus-certification","title":"CompTIA Security+ Certification","authors":["dudu"],"tags":["security","cyber","certification"]},"unlisted":false,"nextItem":{"title":"About Certifications","permalink":"/my-blog/blog/about-certifications"}},"content":"## About\\n\\nCertification `CompTIA Security+ Certification`, also known as `SY0-701`.\\n\\nThe definition of certification is as follow:\\n\\n> CompTIA Security+ is the premier global certification that establishes the essential skills required for core security functions and a career in IT security.\\n> \\n> It showcases professionals\' capabilities in securing networks, applications, and devices, ensuring data integrity, confidentiality, and availability.\\n> \\n> CompTIA Security+ focuses on practical, hands-on skills to tackle real-world challenges.\\n\\n## Tips\\n\\nSome materials used in the study for the certification:\\n- Course: [Udemy - CompTIA Security+ (SY0-701) Complete Course](https://www.udemy.com/course/securityplus).\\n- Simulations: [Udemy - CompTIA Security+ (SY0-701) Practice Exams Set 1](https://www.udemy.com/course/comptia-security-sy0-701-practice-exams).\\n- Also created some [Anki](https://apps.ankiweb.net) Cards to help remembering all the names an acronyms.\\n\\nSee my certification badge [here](https://www.credly.com/badges/4a19dd33-9263-47b1-8682-678cae0f119f/public_url).\\n\\n## Mind Map\\n\\nJust a part of the \\"Mind Map\\" I created on my journey to get the certification.\\n\\nGeneral Security Concepts\\n\\n![Mind Map - General Security Concepts 1](/img/blog/security/sec-1.png)\\n\\nThreats, Vulnerabilities and mitigations\\n\\n![Mind Map - Threats, Vulnerabilities and mitigations 1](/img/blog/security/sec-2.png)\\n\\nSecurity Architecture\\n\\n![Mind Map - Security Architecture 1](/img/blog/security/sec-3.png)\\n\\nSecurity Operations\\n\\n![Mind Map - Security Operations 1](/img/blog/security/sec-4.png)\\n\\nSecurity Program Management and oversight\\n\\n![Mind Map - Security Program Management and oversight 1](/img/blog/security/sec-5.png)"},{"id":"about-certifications","metadata":{"permalink":"/my-blog/blog/about-certifications","source":"@site/blog/2024-02-27-about-certifications.md","title":"About Certifications","description":"Just a few thoughts on certifications:","date":"2024-02-27T00:00:00.000Z","formattedDate":"February 27, 2024","tags":[{"label":"aws","permalink":"/my-blog/blog/tags/aws"},{"label":"psm","permalink":"/my-blog/blog/tags/psm"},{"label":"devops","permalink":"/my-blog/blog/tags/devops"},{"label":"certification","permalink":"/my-blog/blog/tags/certification"}],"readingTime":0.405,"hasTruncateMarker":false,"authors":[{"name":"Dudu Kling","title":"Blog Owner","url":"https://github.com/DuduKling","imageURL":"https://dudukling.github.io/assets/images/avatar.png","key":"dudu"}],"frontMatter":{"slug":"about-certifications","title":"About Certifications","authors":["dudu"],"tags":["aws","psm","devops","certification"]},"unlisted":false,"prevItem":{"title":"CompTIA Security+ Certification","permalink":"/my-blog/blog/comptia-security-plus-certification"},"nextItem":{"title":"DevOps Professional Certification","permalink":"/my-blog/blog/devops-certification"}},"content":"Just a few thoughts on certifications:\\n\\nCertifications are a very controversial topic, but I really couldn\'t care less.\\n\\nI see certifications as a way to continually acquiring new knowledge and applying it everywhere.\\n\\nA professional\'s competences are mix of knowledge, skill, and attitude.\\n\\nWhat I see as a good professional, is someone who continually invests in their self-development, acquires new knowledge, applies their knowledge by delivering to the environment they are working in, and, most importantly, invests in their soft skills."},{"id":"devops-certification","metadata":{"permalink":"/my-blog/blog/devops-certification","source":"@site/blog/2024-02-15-devops-certification.md","title":"DevOps Professional Certification","description":"About","date":"2024-02-15T00:00:00.000Z","formattedDate":"February 15, 2024","tags":[{"label":"devops","permalink":"/my-blog/blog/tags/devops"},{"label":"certification","permalink":"/my-blog/blog/tags/certification"}],"readingTime":1.09,"hasTruncateMarker":false,"authors":[{"name":"Dudu Kling","title":"Blog Owner","url":"https://github.com/DuduKling","imageURL":"https://dudukling.github.io/assets/images/avatar.png","key":"dudu"}],"frontMatter":{"slug":"devops-certification","title":"DevOps Professional Certification","authors":["dudu"],"tags":["devops","certification"]},"unlisted":false,"prevItem":{"title":"About Certifications","permalink":"/my-blog/blog/about-certifications"},"nextItem":{"title":"PSM I Certification","permalink":"/my-blog/blog/psm-certification"}},"content":"## About\\n\\nCertification `EXIN DevOps Professional`, also known as `DEVOPSP`.\\n\\nThe definition of certification is as follow:\\n\\n> This EXIN DevOps Professional certification has been designed to test IT professionals on their background knowledge and understanding of essential DevOps practices.\\n> \\n> Created as a stepping-stone to the EXIN DevOps Master certification, this certification looks at the Three Ways, the good habits of change control, and maintaining security compliance.\\n\\n## Tips\\n\\nThis is by far the least important/relevant certification I have, but I learned a lot studying for it, so for me it\'s worth it.\\n\\nSome materials used in the study for the certification:\\n- Book: `DevOps Handbook`.\\n- Course: [Estabilis Academy - DevOps Professional Online](https://academy.estabil.is/courses/devops-professional-online) (pt-br).\\n- Simulations: You can find some questions to practice on the internet.\\n\\nSee my certification badge [here](https://app.exeed.pro/holder/badge/168853).\\n\\n## Mind Map\\n\\nJust a part of the \\"Mind Map\\" I created on my journey to get the certification.\\n\\nBasic Concepts & Good Quotes\\n\\n![Mind Map - Basic Concepts & Good Quotes](/img/blog/devops/devops-1.png)\\n\\nFirst Way\\n\\n![Mind Map - First Way](/img/blog/devops/devops-2.png)\\n\\nSecond Way\\n\\n![Mind Map - Second Way](/img/blog/devops/devops-3.png)\\n\\nThird Way\\n\\n![Mind Map - Third Way](/img/blog/devops/devops-4.png)\\n\\nSecurity and Transformation\\n\\n![Mind Map - Security and Transformation](/img/blog/devops/devops-5.png)\\n\\nExtra Concepts part 1\\n\\n![Mind Map - Extra Concepts part 1](/img/blog/devops/devops-6.png)\\n\\nExtra Concepts part 2\\n\\n![Mind Map - Extra Concepts part 2](/img/blog/devops/devops-7.png)"},{"id":"psm-certification","metadata":{"permalink":"/my-blog/blog/psm-certification","source":"@site/blog/2023-01-20-psm-certification.md","title":"PSM I Certification","description":"About","date":"2023-01-20T00:00:00.000Z","formattedDate":"January 20, 2023","tags":[{"label":"psm","permalink":"/my-blog/blog/tags/psm"},{"label":"certification","permalink":"/my-blog/blog/tags/certification"}],"readingTime":0.82,"hasTruncateMarker":false,"authors":[{"name":"Dudu Kling","title":"Blog Owner","url":"https://github.com/DuduKling","imageURL":"https://dudukling.github.io/assets/images/avatar.png","key":"dudu"}],"frontMatter":{"slug":"psm-certification","title":"PSM I Certification","authors":["dudu"],"tags":["psm","certification"]},"unlisted":false,"prevItem":{"title":"DevOps Professional Certification","permalink":"/my-blog/blog/devops-certification"},"nextItem":{"title":"AWS Certified Cloud Practitioner Certification","permalink":"/my-blog/blog/aws-ccp-certification"}},"content":"## About\\n\\nCertification `Professional Scrum Master\u2122 I`, also known as `PSM I`.\\n\\nThe definition of certification is as follow:\\n\\n> The Professional Scrum Master\u2122 I (PSM I) certification validates your knowledge of the Scrum framework, the Scrum Master accountabilities and how to apply Scrum. \\n\\n## Tips\\n\\nSome materials used in the study for the certification:\\n- Primary resource: `Scrum Guide`.\\n- Primary Course: [Udemy - Forma\xe7\xe3o total em Scrum](https://www.udemy.com/course/formacao-total-em-scrum) (pt-br).\\n- Other Course: [Alura](https://www.alura.com.br)\'s Scrum courses in Agile training (pt-br).\\n- Simulations: [Udemy - Simulados para certifica\xe7\xf5es Scrum Master](https://www.udemy.com/course/simulados-para-certificacoes-scrum-master) (pt-br).\\n- Other resources: Read a good part of the articles on the certification website as study recommendations, the \\"Scrum Master Learning Path\\".\\n\\nSee my certification badge [here](https://www.credly.com/badges/572249e3-f991-4198-948d-3c3d61b06c8c/public_url).\\n\\n## Mind Map\\n\\nJust a part of the \\"Mind Map\\" I created on my journey to get the certification.\\n\\nManifesto\\n\\n![Mind Map - Manifesto](/img/blog/psm/psm-1.png)\\n\\nScrum part 1\\n\\n![Mind Map - Scrum part 1](/img/blog/psm/psm-2.png)\\n\\nScrum part 2\\n\\n![Mind Map - Scrum part 2](/img/blog/psm/psm-3.png)\\n\\nNexus\\n\\n![Mind Map - Nexus](/img/blog/psm/psm-4.png)"},{"id":"aws-ccp-certification","metadata":{"permalink":"/my-blog/blog/aws-ccp-certification","source":"@site/blog/2021-09-05-aws-ccp-certification.md","title":"AWS Certified Cloud Practitioner Certification","description":"About","date":"2021-09-05T00:00:00.000Z","formattedDate":"September 5, 2021","tags":[{"label":"aws","permalink":"/my-blog/blog/tags/aws"},{"label":"certification","permalink":"/my-blog/blog/tags/certification"}],"readingTime":1.005,"hasTruncateMarker":false,"authors":[{"name":"Dudu Kling","title":"Blog Owner","url":"https://github.com/DuduKling","imageURL":"https://dudukling.github.io/assets/images/avatar.png","key":"dudu"}],"frontMatter":{"slug":"aws-ccp-certification","title":"AWS Certified Cloud Practitioner Certification","authors":["dudu"],"tags":["aws","certification"]},"unlisted":false,"prevItem":{"title":"PSM I Certification","permalink":"/my-blog/blog/psm-certification"}},"content":"## About\\n\\nCertification `Professional Scrum Master\u2122 I`, also known as `PSM I`.\\n\\nThe definition of certification is as follow:\\n\\n> The AWS Certified Cloud Practitioner validates foundational, high-level understanding of AWS Cloud, services, and terminology.\\n> \\n> This is a good starting point on the AWS Certification journey for individuals with no prior IT or cloud experience switching to a cloud career or for line-of-business employees looking for foundational cloud literacy.\\n\\n## Tips\\n\\nSome materials used in the study for the certification:\\n- Primary resource: `AWS Web Documentation`.\\n- Course: [Udemy - AWS Certified Cloud Practitioner](https://www.udemy.com/course/aws-certified-cloud-practitioner-new).\\n- Simulations: There are some books on the internet with lots of questions to practice.\\n- Also created some [Anki](https://apps.ankiweb.net) Cards to help remembering all the names an acronyms.\\n\\nSee my certification badge [here](https://www.credly.com/badges/01ae0295-4d60-4276-b6c2-d2f17abb84f2/public_url).\\n\\n## Mind Map\\n\\nJust a part of the \\"Mind Map\\" I created on my journey to get the certification.\\n\\nBilling and Pricing\\n\\n![Mind Map - Billing and Pricing](/img/blog/aws/aws-1.png)\\n\\nCloud Concepts AND Security and Compliance\\n\\n![Mind Map - Cloud Concepts AND Security and Compliance](/img/blog/aws/aws-2.png)\\n\\nTechnologies 1\\n\\n![Mind Map - Technologies 1](/img/blog/aws/aws-3.png)\\n\\nTechnologies 3\\n\\n![Mind Map - Technologies 3](/img/blog/aws/aws-4.png)\\n\\nTechnologies 2\\n\\n![Mind Map - Technologies 2](/img/blog/aws/aws-5.png)\\n\\nTechnologies 4\\n\\n![Mind Map - Technologies 4](/img/blog/aws/aws-6.png)"}]}')}}]);